/**
 * FreeWire Phase 16 — Claude Tool Use 자율 에이전트
 *
 * 자연어 요구사항 → HTML/CSS/JS 완성까지 자율 루프
 *
 * 동작 방식:
 *   1. Claude API Tool Use로 FreeWire 도구를 호출
 *   2. 그래프 생성 → 평가 → 개선 → 실행 반복
 *   3. API 키 없으면 직접 모듈 호출 폴백
 */

'use strict';

let Anthropic;
try {
  Anthropic = require('@anthropic-ai/sdk');
} catch (_) {
  Anthropic = null;
}

const { TOOLS, executeTool } = require('./tools');
const { buildSystemPrompt }  = require('./system-prompt');

// ─── FreeWireAgent ────────────────────────────────────────────

class FreeWireAgent {
  /**
   * @param {object} options
   * @param {number}  [options.maxTurns=10]    — 최대 Tool Use 루프 횟수
   * @param {number}  [options.targetScore=80] — 목표 평가 점수 (0-100)
   * @param {string}  [options.apiKey]         — Anthropic API 키
   * @param {string}  [options.serverUrl]      — FreeWire API 서버 URL
   * @param {string}  [options.model]          — Claude 모델명
   */
  constructor(options = {}) {
    this.maxTurns    = options.maxTurns    ?? 10;
    this.targetScore = options.targetScore ?? 80;
    this.apiKey      = options.apiKey      || process.env.ANTHROPIC_API_KEY || null;
    this.serverUrl   = options.serverUrl   || 'http://localhost:4010';
    this.model       = options.model       || 'claude-haiku-4-5-20251001';
  }

  /**
   * 자율 에이전트 실행
   * @param {string} userRequest — 자연어 요구사항
   * @returns {AgentResult}
   */
  async run(userRequest) {
    if (!Anthropic || !this.apiKey) {
      return this._fallbackRun(userRequest);
    }

    const client = new Anthropic({ apiKey: this.apiKey });
    const toolOptions = { serverUrl: this.serverUrl, apiKey: this.apiKey };

    const messages = [{ role: 'user', content: userRequest }];
    const agentState = { graph: null, score: 0, html: '', css: '', js: '', previewUrl: null };
    let turn = 0;

    while (turn < this.maxTurns) {
      let response;
      try {
        response = await client.messages.create({
          model:      this.model,
          max_tokens: 4096,
          system:     buildSystemPrompt(this.targetScore, this.maxTurns),
          tools:      TOOLS,
          messages,
        });
      } catch (e) {
        console.error('[Agent] Claude API 오류:', e.message);
        break;
      }

      // 종료 조건
      if (response.stop_reason === 'end_turn' || response.stop_reason === 'max_tokens') {
        break;
      }

      // Tool Use 처리
      if (response.stop_reason === 'tool_use') {
        const toolBlocks = response.content.filter(b => b.type === 'tool_use');
        const toolResults = [];

        for (const block of toolBlocks) {
          let result;
          try {
            result = await executeTool(block.name, block.input, toolOptions);
          } catch (e) {
            result = { error: e.message };
          }

          // agentState 업데이트
          if (block.name === 'freewire_generate' && result.graph) {
            agentState.graph = result.graph;
          }
          if (block.name === 'freewire_evaluate' && typeof result.score === 'number') {
            agentState.score = result.score;
          }
          if (block.name === 'freewire_execute') {
            if (result.html !== undefined) agentState.html = result.html;
            if (result.css  !== undefined) agentState.css  = result.css;
            if (result.js   !== undefined) agentState.js   = result.js;
          }
          if (block.name === 'freewire_preview' && result.url) {
            agentState.previewUrl = result.url;
          }

          toolResults.push({
            type:        'tool_result',
            tool_use_id: block.id,
            content:     JSON.stringify(result),
          });
        }

        messages.push({ role: 'assistant', content: response.content });
        messages.push({ role: 'user',      content: toolResults });
        turn++;
      } else {
        // 예상치 못한 stop_reason
        break;
      }
    }

    return {
      html:       agentState.html,
      css:        agentState.css,
      js:         agentState.js,
      graph:      agentState.graph,
      score:      agentState.score,
      turns:      turn,
      previewUrl: agentState.previewUrl,
      fallback:   false,
    };
  }

  /**
   * API 키 없을 때: 직접 모듈 파이프라인 실행
   * generate(규칙기반) → evaluate → compile → execute
   */
  async _fallbackRun(userRequest) {
    const { aiGenerateGraph }  = require('../api/ai-graph-generator');
    const { IntentEvaluator }  = require('../intent/evaluator');
    const { GraphCompiler }    = require('../compiler/graph-compiler');
    const { FreeExecutor }     = require('../api/free-executor');
    const { Graph }            = require('../core/graph');
    const { _graphNodesToMap, _graphEdgesToMap } = require('./tools');

    // 1) 규칙 기반 그래프 생성
    const generated = await aiGenerateGraph(userRequest, null);
    const graph = generated.graph || { nodes: [], edges: [] };

    // 2) 평가
    const nodesMap = _graphNodesToMap(graph.nodes);
    const wiresMap = _graphEdgesToMap(graph.edges);
    const evaluator = new IntentEvaluator();
    const report = evaluator.evaluate(nodesMap, wiresMap, userRequest);

    // 3) 컴파일 + 실행
    let html = '', css = '', js = '';
    try {
      const graphObj = Graph.fromJSON(graph);
      const compiler = new GraphCompiler();
      const compiled = compiler.compile(graphObj);
      if (!compiled.errors || compiled.errors.length === 0) {
        const executor = new FreeExecutor();
        const executed = executor.execute(compiled.code, graph);
        html = executed.html || '';
        css  = executed.css  || '';
        js   = executed.js   || '';
      }
    } catch (_) {}

    return {
      html,
      css,
      js,
      graph,
      score:      report.score,
      turns:      0,
      previewUrl: null,
      fallback:   true,
    };
  }
}

module.exports = { FreeWireAgent };

