/**
 * FreeWire Agent — Tool 정의 + executeTool() 래퍼
 *
 * Claude API tools 파라미터에 등록할 5개 도구:
 *   freewire_generate, freewire_compile, freewire_execute,
 *   freewire_evaluate, freewire_preview
 *
 * executeTool(): HTTP → 실패 시 직접 모듈 호출 fallback
 */

'use strict';

const http = require('http');

// ─── Tool 정의 (Claude API tools 파라미터용) ───────────────────

const TOOLS = [
  {
    name: 'freewire_generate',
    description: '자연어 프롬프트를 받아 FreeWire 노드 그래프 JSON을 생성합니다.',
    input_schema: {
      type: 'object',
      properties: {
        prompt: {
          type: 'string',
          description: '생성할 UI를 설명하는 자연어 (예: "로그인 폼", "카운터 앱")',
        },
      },
      required: ['prompt'],
    },
  },
  {
    name: 'freewire_compile',
    description: 'FreeWire 그래프 JSON을 FreeLang .free 코드로 컴파일합니다.',
    input_schema: {
      type: 'object',
      properties: {
        graph: {
          type: 'object',
          description: 'FreeWire 그래프 JSON { nodes, edges }',
        },
      },
      required: ['graph'],
    },
  },
