      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch (e) { reject(new Error('JSON 파싱 실패')); }
      });
    });

    req.setTimeout(timeoutMs, () => { req.destroy(); reject(new Error('HTTP 타임아웃')); });
    req.on('error', reject);
    req.write(payload);
    req.end();
  });
}

