/**
 * Graph → fir IR 구조체 (Phase 17)
 *
 * fir IR 형식:
 *   { module, functions: [{ name, params, body: [Instruction] }] }
 *
 * Instruction 타입:
 *   { op: 'const',    id, type, value }
 *   { op: 'call',     id, fn, args }
 *   { op: 'branch',   cond, then, else }
 *   { op: 'ret',      value }
 *
 * @param {Graph|object} input
 * @returns {{ ir: object, errors: string[], warnings: string[] }}
 */
compileToIR(input) {
  this.errors   = [];
  this.warnings = [];

  const graph  = input instanceof Graph ? input : Graph.fromJSON(input);
  const sorted = graph.topologicalSort();
  const bridge = getBridge();

  const instructions = [];
  const idMap = {};  // nodeId → IR id

  let irIdCtr = 0;
  const nextId = () => `%${irIdCtr++}`;

  for (const node of sorted) {
    if (node.type === 'data') {
      const id = nextId();
      idMap[node.id] = id;
      instructions.push({
        op:    'const',
        id,
        type:  node.dataType ?? 'any',
        value: node.props?.value ?? null,
        label: node.props?.name ?? node.id,
      });
    } else if (node.type === 'logic') {
      if (node.logicType === 'if') {
        const condEdge = graph.incomingEdges(node.id).find(e => e.to.portId === 'condition');
        const cond = condEdge ? (idMap[condEdge.from.nodeId] ?? condEdge.from.nodeId) : node.props?.condition ?? 'true';
        instructions.push({ op: 'branch', cond, then: node.id + '_then', else: node.id + '_else' });
      } else if (node.logicType === 'function') {
        const id = nextId();
        idMap[node.id] = id;
        instructions.push({
          op:     'call',
          id,
          fn:     node.props?.name ?? node.id,
          args:   node.props?.params ?? [],
          body:   node.props?.body ?? '',
        });
      }
    } else if (node.type === 'component') {
      const id = nextId();
      idMap[node.id] = id;
      const childEdges = graph.incomingEdges(node.id).filter(e => e.to.portId === 'children');
      instructions.push({
        op:          'render',
        id,
        componentType: node.componentType ?? node.subtype ?? 'div',
        props:       node.props ?? {},
        children:    childEdges.map(e => idMap[e.from.nodeId] ?? e.from.nodeId),
      });
    } else if (bridge.isStdlibNode(node)) {
      const id = nextId();
      idMap[node.id] = id;
      instructions.push({
        op:   'stdlib',
        id,
        fn:   node.stdlibFn ?? node.props?.fn ?? node.id,
        args: graph.incomingEdges(node.id).map(e => idMap[e.from.nodeId] ?? e.from.nodeId),
      });
    }
  }

  // 루트 render 노드를 ret으로 마무리
  const lastRender = [...instructions].reverse().find(i => i.op === 'render');
  if (lastRender) {
    instructions.push({ op: 'ret', value: lastRender.id });
  } else {
    this.warnings.push('[IR] render 노드 없음 — ret 생략');
  }

  return {
    ir: {
      module:    graph.id,
      functions: [{
        name:   'render',
        params: [],
        body:   instructions,
      }],
    },
    errors:   this.errors,
    warnings: this.warnings,
  };
}

// ─── 내부 빌더 ──────────────────────────────────────────────

