/**
 * FreeWire Phase 16 — Claude Tool Use 자율 에이전트 테스트
 * node src/test/test-phase16.js
 */
'use strict';

let pass = 0, fail = 0;

function test(label, fn) {
  try {
    fn();
    console.log(`  ✓ ${label}`);
    pass++;
  } catch (e) {
    console.error(`  ✗ ${label}: ${e.message}`);
    fail++;
  }
}

async function testAsync(label, fn) {
  try {
    await fn();
    console.log(`  ✓ ${label}`);
    pass++;
  } catch (e) {
    console.error(`  ✗ ${label}: ${e.message}`);
    fail++;
  }
}

function assert(cond, msg = 'assertion failed') {
  if (!cond) throw new Error(msg);
}

const path = require('path');
const { TOOLS, executeTool, _graphNodesToMap, _graphEdgesToMap } = require('../agent/tools');
const { buildSystemPrompt } = require('../agent/system-prompt');
const { FreeWireAgent }     = require('../agent/freewire-agent');

async function main() {

// ── 1. TOOLS 배열 ────────────────────────────────────────────

console.log('\n[tools / TOOLS 배열]');

test('TOOLS가 배열이고 5개 항목 포함', () => {
  assert(Array.isArray(TOOLS));
  assert(TOOLS.length === 5, `TOOLS.length=${TOOLS.length}`);
});

test('freewire_generate — prompt required', () => {
  const t = TOOLS.find(x => x.name === 'freewire_generate');
  assert(t, 'freewire_generate 없음');
  assert(t.input_schema.required.includes('prompt'));
});

test('freewire_compile — graph required', () => {
  const t = TOOLS.find(x => x.name === 'freewire_compile');
  assert(t, 'freewire_compile 없음');
  assert(t.input_schema.required.includes('graph'));
});

test('freewire_execute — graph required', () => {
  const t = TOOLS.find(x => x.name === 'freewire_execute');
  assert(t, 'freewire_execute 없음');
  assert(t.input_schema.required.includes('graph'));
});

test('freewire_evaluate — graph, goal required', () => {
  const t = TOOLS.find(x => x.name === 'freewire_evaluate');
  assert(t, 'freewire_evaluate 없음');
  assert(t.input_schema.required.includes('graph'));
  assert(t.input_schema.required.includes('goal'));
});

// ── 2. 헬퍼: 배열 → Map 변환 ─────────────────────────────────

console.log('\n[tools / 배열→Map 변환]');

test('_graphNodesToMap — 노드 배열 → Map', () => {
  const nodes = [{ id: 'n1', type: 'component' }, { id: 'n2', type: 'data' }];
  const map = _graphNodesToMap(nodes);
  assert(map instanceof Map);
  assert(map.size === 2);
  assert(map.get('n1').type === 'component');
});

test('_graphNodesToMap — 빈 배열', () => {
  const map = _graphNodesToMap([]);
  assert(map.size === 0);
});

test('_graphEdgesToMap — 엣지 배열 → Map', () => {
  const edges = [{ id: 'e1', from: { nodeId: 'n1' }, to: { nodeId: 'n2' } }];
  const map = _graphEdgesToMap(edges);
  assert(map instanceof Map);
  assert(map.size === 1);
});

// ── 3. freewire_evaluate 직접 호출 ───────────────────────────

console.log('\n[tools / freewire_evaluate 직접호출]');

const BAD_SERVER = { serverUrl: 'http://localhost:99999' };

await testAsync('빈 그래프 평가 — score 반환', async () => {
  const result = await executeTool('freewire_evaluate', {
    graph: { nodes: [], edges: [] },
    goal: '테스트'
  }, BAD_SERVER);
  assert(typeof result.score === 'number', `score 없음: ${JSON.stringify(result)}`);
  assert(result.score === 0, `빈 그래프 score=${result.score}, 0 기대`);
});

await testAsync('빈 그래프 평가 — violations 배열', async () => {
  const result = await executeTool('freewire_evaluate', {
    graph: { nodes: [], edges: [] },
    goal: '테스트'
  }, BAD_SERVER);
  assert(Array.isArray(result.violations), 'violations 배열 아님');
});

await testAsync('노드 있는 그래프 평가 — score > 0', async () => {
  const graph = {
    nodes: [
      { id: 'n1', type: 'component', componentType: 'button', inputs: [], outputs: [], props: { label: '클릭' } }
    ],
    edges: []
  };
  const result = await executeTool('freewire_evaluate', { graph, goal: '버튼 UI' }, BAD_SERVER);
  assert(typeof result.score === 'number');
  assert(result.score >= 0);
});

// ── 4. freewire_compile 직접 호출 ────────────────────────────

console.log('\n[tools / freewire_compile 직접호출]');

const MINIMAL_GRAPH = {
  id: 'test',
  nodes: [
    { id: 'n1', type: 'component', componentType: 'text', inputs: [], outputs: [], props: { content: '안녕', tag: 'h1' } }
  ],
  edges: []
};

await testAsync('최소 그래프 컴파일 — code 반환', async () => {
  const result = await executeTool('freewire_compile', { graph: MINIMAL_GRAPH }, BAD_SERVER);
  assert(typeof result.code === 'string', `code 없음: ${JSON.stringify(result)}`);
});

await testAsync('freewire_compile — errors 배열', async () => {
  const result = await executeTool('freewire_compile', { graph: MINIMAL_GRAPH }, BAD_SERVER);
  assert(Array.isArray(result.errors), 'errors 배열 아님');
});

await testAsync('freewire_compile — warnings 배열', async () => {
  const result = await executeTool('freewire_compile', { graph: MINIMAL_GRAPH }, BAD_SERVER);
  assert(Array.isArray(result.warnings), 'warnings 배열 아님');
});

// ── 5. freewire_execute 직접 호출 ────────────────────────────

console.log('\n[tools / freewire_execute 직접호출]');

await testAsync('최소 그래프 실행 — html/css/js 반환', async () => {
  const result = await executeTool('freewire_execute', { graph: MINIMAL_GRAPH }, BAD_SERVER);
  assert(typeof result.html === 'string', `html 없음`);
  assert(typeof result.css  === 'string', `css 없음`);
  assert(typeof result.js   === 'string', `js 없음`);
});

await testAsync('freewire_execute — html이 비어있지 않음', async () => {
  const result = await executeTool('freewire_execute', { graph: MINIMAL_GRAPH }, BAD_SERVER);
  assert(result.html.length > 0, 'html 비어있음');
});

// ── 6. freewire_preview 직접 호출 ────────────────────────────

console.log('\n[tools / freewire_preview 직접호출]');

await testAsync('서버 없을 때 fallback:true 반환', async () => {
  const result = await executeTool('freewire_preview', { graph: MINIMAL_GRAPH }, BAD_SERVER);
  assert(result.fallback === true, 'fallback 아님');
});

// ── 7. system-prompt ─────────────────────────────────────────

console.log('\n[system-prompt]');

test('buildSystemPrompt — 문자열 반환', () => {
  const prompt = buildSystemPrompt(80, 10);
  assert(typeof prompt === 'string');
  assert(prompt.length > 50);
});

test('buildSystemPrompt — targetScore 포함', () => {
  const prompt = buildSystemPrompt(75, 5);
  assert(prompt.includes('75'));
});

// ── 8. FreeWireAgent 초기화 ───────────────────────────────────

console.log('\n[FreeWireAgent / 초기화]');

test('기본 옵션 확인', () => {
  const agent = new FreeWireAgent();
  assert(agent.maxTurns    === 10);
  assert(agent.targetScore === 80);
  assert(agent.model === 'claude-haiku-4-5-20251001');
});

test('커스텀 옵션 적용', () => {
  const agent = new FreeWireAgent({ maxTurns: 5, targetScore: 70 });
  assert(agent.maxTurns    === 5);
  assert(agent.targetScore === 70);
});

test('apiKey 없어도 인스턴스 생성 가능', () => {
  const agent = new FreeWireAgent({ apiKey: null });
  assert(agent !== null);
});

// ── 9. FreeWireAgent 폴백 run() ──────────────────────────────

console.log('\n[FreeWireAgent / 폴백 run()]');

const agentNoKey = new FreeWireAgent({ apiKey: null });

await testAsync('apiKey 없을 때 폴백 동작', async () => {
  const result = await agentNoKey.run('카운터 앱');
  assert(result !== null);
  assert(result.fallback === true);
});

await testAsync('폴백 결과 — html 필드 존재', async () => {
  const result = await agentNoKey.run('버튼 UI');
  assert(typeof result.html === 'string');
});

await testAsync('폴백 결과 — graph 필드 존재', async () => {
  const result = await agentNoKey.run('입력 폼');
  assert(result.graph !== null && result.graph !== undefined);
});

await testAsync('폴백 결과 — score 필드 존재', async () => {
  const result = await agentNoKey.run('텍스트 표시');
  assert(typeof result.score === 'number');
});

// ── 10. AgentResult 구조 ─────────────────────────────────────

console.log('\n[AgentResult / 구조 검증]');

await testAsync('모든 필드 존재 (turns, score, html, css, js, graph)', async () => {
  const result = await agentNoKey.run('버튼 하나');
  const required = ['turns', 'score', 'html', 'css', 'js', 'graph'];
  for (const field of required) {
    assert(field in result, `${field} 필드 없음`);
  }
});

await testAsync('graph.nodes가 배열', async () => {
  const result = await agentNoKey.run('로그인 버튼');
  assert(Array.isArray(result.graph?.nodes), 'graph.nodes 배열 아님');
});

} // end main()

// ── 최종 결과 ────────────────────────────────────────────────

main().then(() => {
  console.log('\n────────────────────────────────────────────────────────');
  console.log(`Phase 16 테스트: ${pass} 통과 / ${fail} 실패 / 전체 ${pass + fail}`);
  console.log('────────────────────────────────────────────────────────');
  if (fail === 0) {
    console.log('✓ 모든 테스트 통과!');
    process.exit(0);
  } else {
    console.log(`✗ ${fail}개 실패`);
    process.exit(1);
  }
}).catch(e => {
  console.error(e);
  process.exit(1);
});

