const ROOT = path.resolve(__dirname, '../../');

const PHASES = [
  { n:  1, file: 'test-phase1.js'  },
  { n:  2, file: 'test-phase2.js'  },
  { n:  3, file: 'test-phase3.js'  },
  { n:  4, file: 'test-phase4.js'  },
  { n:  5, file: 'test-phase5.js'  },
  { n:  6, file: 'test-phase6.js'  },
  { n:  7, file: 'test-phase7.js'  },
  { n:  8, file: 'test-phase8.js'  },
  { n:  9, file: 'test-phase9.js'  },
  { n: 10, file: 'test-phase10.js' },
  { n: 11, file: 'test-phase11.js' },
  { n: 12, file: 'test-phase12.js' },
  { n: 13, file: 'test-phase13.js' },
  { n: 14, file: 'test-phase14.js' },
  { n: 15, file: 'test-phase15.js' },
  { n: 16, file: 'test-phase16.js' },
];

const W = 56;
const line  = (c = '─') => c.repeat(W);
const pad   = (s, n) => String(s).padEnd(n);

console.log('\n' + line('═'));
console.log(' FreeWire 전체 테스트');
console.log(' ' + new Date().toLocaleString('ko-KR', { timeZone: 'Asia/Seoul' }));
console.log(line('═'));

let totalPass = 0, totalFail = 0;
const results = [];

for (const { n, file } of PHASES) {
  const filePath = path.join(__dirname, file);
  const label = `Phase ${String(n).padStart(2, '0')}`;

  let output = '';
  let exitCode = 0;

  try {
    output = execSync(`node "${filePath}"`, {
      cwd: ROOT,
      timeout: 30000,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
  } catch (e) {
    output   = (e.stdout || '') + (e.stderr || '');
    exitCode = e.status ?? 1;
  }

  // 통과/실패 수 파싱 (다양한 포맷 지원)
  let p = 0, f = 0;

  // 포맷1: "45개 중 45개 통과, 0개 실패"
  let m = output.match(/(\d+)개 중 (\d+)개 통과.*?(\d+)개 실패/);
  if (m) { p = parseInt(m[2]); f = parseInt(m[3]); }

  // 포맷2: "38 passed, 0 failed / 38 total"
  if (!m) {
    m = output.match(/(\d+)\s*passed.*?(\d+)\s*failed/);
    if (m) { p = parseInt(m[1]); f = parseInt(m[2]); }
  }

  // 포맷3: "X 통과 / Y 실패 / 전체 Z"
  if (!m) {
    m = output.match(/(\d+)\s*통과\s*\/\s*(\d+)\s*실패/);
    if (m) { p = parseInt(m[1]); f = parseInt(m[2]); }
  }

  // 포맷4: "전체 통과: X/Y"
  if (!m) {
    m = output.match(/전체 통과:\s*(\d+)\/(\d+)/);
    if (m) { p = parseInt(m[1]); f = parseInt(m[2]) - parseInt(m[1]); }
  }

  // exit code로 최종 판단
  const ok = exitCode === 0 && f === 0;
  const icon = ok ? '✅' : '❌';

  totalPass += p;
  totalFail += f;
  results.push({ label, p, f, ok });

  console.log(`${icon} ${pad(label, 12)} ${pad(p + ' pass', 10)} ${f > 0 ? f + ' fail' : ''}`);
}

// ── 최종 집계 ──────────────────────────────────────────────────
console.log(line());
const allOk = totalFail === 0;
const total = totalPass + totalFail;

console.log(`\n  전체: ${total}개 테스트`);
console.log(`  통과: ${totalPass}개`);
if (totalFail > 0) console.log(`  실패: ${totalFail}개`);

console.log('');
if (allOk) {
  console.log(`🎉 모든 테스트 통과! (${totalPass}/${total})`);
} else {
  console.log(`💥 실패 있음 (${totalPass}/${total})`);
  console.log('\n실패한 Phase:');
  results.filter(r => !r.ok).forEach(r => {
    console.log(`  - ${r.label}: ${r.f}개 실패`);
  });
}
console.log(line('═') + '\n');

process.exit(allOk ? 0 : 1);

