/**
 * FreeWire — AI Graph Generator
 *
 * Claude API → 노드 그래프 JSON 동적 생성
 *
 * 사용자의 자연어 설명을 받아서
 * FreeWire 노드 + 와이어 구조를 생성한다.
 *
 * API 키가 없으면 AINodeGenerator(규칙 기반) 폴백으로 동작한다.
 */

'use strict';

let Anthropic;
try {
  Anthropic = require('@anthropic-ai/sdk');
} catch (_) {
  Anthropic = null;
}

const { AINodeGenerator } = require('../ai/node-generator');

// ─── 노드 타입 레퍼런스 (Claude에게 알려줄 스펙) ─────────────────

const NODE_SPEC = `
# FreeWire 노드 스펙

## 노드 타입

### component 노드 (UI 요소)
- button:    { type:"component", subtype:"button",    props:{label:"텍스트", variant:"primary|secondary|ghost|danger"} }
- text:      { type:"component", subtype:"text",      props:{content:"텍스트", tag:"h1|h2|h3|p|span|label"} }
- input:     { type:"component", subtype:"input",     props:{placeholder:"힌트", type:"text|email|password|number"} }
- card:      { type:"component", subtype:"card",      props:{title:"제목"} }
- container: { type:"component", subtype:"container", props:{direction:"row|column", gap:"8px"} }
- image:     { type:"component", subtype:"image",     props:{src:"url", alt:"설명"} }
- badge:     { type:"component", subtype:"badge",     props:{text:"배지", color:"blue|green|red|yellow"} }

### data 노드 (데이터 흐름)
- state:     { type:"data", subtype:"state",   props:{name:"변수명", initial:"초기값"} }
- const:     { type:"data", subtype:"const",   props:{value:"값", valueType:"string|number|boolean"} }
- array:     { type:"data", subtype:"array",   props:{items:"[]"} }
- props:     { type:"data", subtype:"props",   props:{schema:"{}"} }

### logic 노드 (제어 흐름)
- handler:   { type:"logic", subtype:"handler",   props:{name:"함수명"} }
- setState:  { type:"logic", subtype:"setState",  props:{stateName:"변수명", value:"새값"} }
- ifelse:    { type:"logic", subtype:"ifelse",    props:{condition:"조건식"} }

## 와이어 구조
{ from: "노드ID", fromPort: 0, to: "노드ID", toPort: 0 }

## 포트 컨벤션
- button  inputs[0]=props, inputs[1]=onClick(핸들러 연결)
- text    inputs[0]=content(데이터 바인딩)
- input   inputs[0]=value, inputs[1]=onChange
- card    inputs[0..n]=children
- container inputs[0..n]=children
- handler → button: { from:handlerId, fromPort:0, to:buttonId, toPort:1 }
- state   → text:   { from:stateId,   fromPort:0, to:textId,   toPort:0 }
`;

const SYSTEM_PROMPT = `당신은 FreeWire 노드 그래프 생성기입니다.
사용자의 UI 설명을 읽고 FreeWire 노드 그래프 JSON을 생성합니다.

${NODE_SPEC}

## 응답 형식 (반드시 순수 JSON만 반환, 설명 텍스트 없이)

{
  "label": "그래프 이름",
  "nodes": [
    { "id": "n1", "type": "component", "subtype": "button", "label": "버튼[로그인]", "props": {"label":"로그인","variant":"primary"} },
    ...
  ],
  "edges": [
    { "id": "e1", "from": "n2", "fromPort": 0, "to": "n1", "toPort": 1 },
    ...
  ]
}

## 규칙
1. 노드 ID는 "n1", "n2" 형식
2. 와이어 ID는 "e1", "e2" 형식
3. 버튼이 있으면 반드시 handler 노드와 연결 (toPort: 1)
4. state 노드가 있으면 반드시 text 노드에 바인딩 (fromPort:0, toPort:0)
5. 관련 노드들은 card나 container로 묶기
6. label은 "타입[이름]" 형식 (예: "버튼[로그인]", "상태[count]")
7. 사용자 요청을 정확히 반영 — 없다고 한 것은 만들지 않기
8. 순수 JSON만 반환 (코드블록, 설명 없음)`;

// ─── 메인 함수 ──────────────────────────────────────────────────

/**
 * 자연어 프롬프트 → FreeWire 그래프 JSON 생성
 *
 * @param {string} prompt   - 자연어 UI 설명
 * @param {string} [apiKey] - Claude API 키 (없으면 규칙 기반 폴백)
 * @returns {Promise<object>} { graph, label, nodeCount, edgeCount, source, rawPrompt }
 */
async function aiGenerateGraph(prompt, apiKey) {
  // ── 입력 검증 ────────────────────────────────────────────────
  if (!prompt || typeof prompt !== 'string') {
    throw new Error('prompt는 비어 있지 않은 문자열이어야 합니다');
  }
  const trimmed = prompt.trim();
  if (trimmed.length === 0) {
    throw new Error('prompt는 비어 있지 않은 문자열이어야 합니다');
  }
  if (trimmed.length > 2000) {
    throw new Error('prompt가 너무 깁니다 (최대 2000자)');
  }

  const key = apiKey || process.env.ANTHROPIC_API_KEY;

  // ── API 키 없음 → 규칙 기반 폴백 ─────────────────────────────
  if (!key || !Anthropic) {
    return _fallbackGenerate(trimmed);
  }

  // ── Claude API 호출 ───────────────────────────────────────────
  try {
    const client = new Anthropic({ apiKey: key });

    const message = await client.messages.create({
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 2048,
      system: SYSTEM_PROMPT,
      messages: [{ role: 'user', content: trimmed }],
    });

    const raw = message.content[0]?.text ?? '';
    const graph = parseGraphJSON(raw);

    // 레이아웃 계산
    graph.nodes = applyLayout(graph.nodes);

    return {
      graph,
      label:     graph.label,
      nodeCount: graph.nodes.length,
      edgeCount: graph.edges.length,
      source:    'claude-api',
      model:     message.model,
      usage:     message.usage,
      rawPrompt: trimmed,
    };
  } catch (e) {
    // API 실패 시 규칙 기반 폴백
    if (e.message && e.message.includes('API 키')) throw e;  // 인증 오류는 재전파
    const fallback = await _fallbackGenerate(trimmed);
    fallback.fallbackReason = e.message;
    return fallback;
  }
}

// ─── 규칙 기반 폴백 ─────────────────────────────────────────────

async function _fallbackGenerate(prompt) {
  const generator = new AINodeGenerator();
  const result = await generator.generate(prompt);

  // nodes 객체 → 배열로 변환 (parseGraphJSON 포맷과 통일)
  const nodesArray = Object.values(result.nodes ?? {});
  const edgesArray = (result.edges ?? []).map((e, i) => ({
    id:       e.id ?? `e${i + 1}`,
    from:     e.fn ?? e.from,
    fromPort: e.fp ?? e.fromPort ?? 0,
    to:       e.tn ?? e.to,
    toPort:   e.tp ?? e.toPort ?? 0,
  }));

  // 레이아웃 적용
  const nodesWithLayout = applyLayout(nodesArray);

  const graph = {
    label: result.label ?? 'AI 생성 그래프',
    nodes: nodesWithLayout,
    edges: edgesArray,
  };

  return {
    graph,
    label:     graph.label,
    nodeCount: nodesWithLayout.length,
    edgeCount: edgesArray.length,
    source:    'rule-based-fallback',
    intent:    result.intent,
    rawPrompt: prompt,
  };
}

// ─── JSON 파싱 (방어적) ─────────────────────────────────────────

function parseGraphJSON(raw) {
  // 코드블록 제거
  let text = raw.trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();

  // JSON 시작 위치 찾기
  const start = text.indexOf('{');
  const end   = text.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('JSON 응답을 찾을 수 없습니다');

  text = text.slice(start, end + 1);

  let graph;
  try {
    graph = JSON.parse(text);
  } catch (e) {
    console.error('[AI] JSON 파싱 실패. 원본(200자):', text.slice(0, 200));
    throw new Error('Claude API 응답을 JSON으로 파싱하지 못했습니다: ' + e.message);
  }

  // 필수 필드 보장
  if (!graph.nodes) graph.nodes = [];
  if (!graph.edges) graph.edges = [];
  if (!graph.label) graph.label = 'AI 생성 그래프';

  // edge id 보장
  graph.edges = graph.edges.map((e, i) => ({
    id: e.id ?? `e${i + 1}`,
    from:      e.from      ?? e.fromNode,
    fromPort:  e.fromPort  ?? 0,
    to:        e.to        ?? e.toNode,
    toPort:    e.toPort    ?? 0,
  }));

  return graph;
}

// ─── 자동 레이아웃 ──────────────────────────────────────────────

function applyLayout(nodes) {
  const W = 200, H = 130, GAP_X = 70, GAP_Y = 24;

  // type 순서: data → logic → component
  const ORDER = { data: 0, logic: 1, component: 2 };
  const cols   = { data: [], logic: [], component: [] };

  for (const n of nodes) {
    const col = cols[n.type] ?? cols.component;
    col.push(n);
  }

  let x = 80;
  const result = [];

  for (const [typeName, col] of Object.entries(cols)) {
    if (col.length === 0) continue;
    col.forEach((n, i) => {
      result.push({ ...n, position: { x, y: 80 + i * (H + GAP_Y) } });
    });
    x += W + GAP_X;
  }

  return result;
}

module.exports = { aiGenerateGraph };

