const { aiGenerateGraph } = require('./src/api/ai-graph-generator');
const { IntentEvaluator } = require('./src/intent/evaluator');
const { GraphCompiler }   = require('./src/compiler/graph-compiler');
const { FreeExecutor }    = require('./src/api/free-executor');

function normalizeGraph(graph) {
  const edges = (graph.edges||[]).map((e,i)=>({
    id: e.id||'e-'+i,
    from:{ nodeId: typeof e.from==='string'?e.from:(e.from?.nodeId||''), portId:e.fromPort||0, portType:'any' },
    to:  { nodeId: typeof e.to  ==='string'?e.to  :(e.to?.nodeId  ||''), portId:e.toPort  ||0, portType:'any' },
  }));
  const nodes = (graph.nodes||[]).map(n=>({ inputs:[], outputs:[], props:{}, ...n }));
  return { ...graph, nodes, edges };
}

async function pipeline(prompt) {
  console.log('═'.repeat(50));
  console.log(' 입력:', prompt);
  console.log('═'.repeat(50));

  // 1. 자연어 → 그래프
  const gen = await aiGenerateGraph(prompt, null);
  const g = gen.graph;
  console.log(\`\n① 그래프 생성  노드 \${g.nodes.length}개 / 엣지 \${g.edges.length}개\`);
  g.nodes.forEach(n => console.log(\`   - \${n.label||n.id} (\${n.subtype||n.type})\`));

  // 2. 평가
  const nm = new Map(g.nodes.map(n=>[n.id,n]));
  const wm = new Map((g.edges||[]).map((e,i)=>[e.id||'e-'+i, { fn: typeof e.from==='string'?e.from:e.fn, tn: typeof e.to==='string'?e.to:e.tn, fp:e.fromPort||0, tp:e.toPort||0 }]));
  const report = new IntentEvaluator().evaluate(nm, wm, prompt);
  console.log(\`\n② 평가         점수 \${report.score}점 | 통과: \${report.passed}\`);
  console.log(\`   충족: \${report.satisfiedFacts.join(', ')}\`);
  if(report.missingFacts.length) console.log(\`   미충족: \${report.missingFacts.join(', ')}\`);

  // 3. 컴파일
  const ng = normalizeGraph(g);
  const { Graph } = require('./src/core/graph');
  const compiler = new GraphCompiler();
  const compiled = compiler.compile(ng);
  console.log(\`\n③ 컴파일       오류 \${compiled.errors.length}개 / 경고 \${compiled.warnings.length}개\`);
  console.log('   .free 코드 미리보기:');
  compiled.code.split('\n').slice(0,8).forEach(l => console.log('   '+l));

  // 4. 실행
  const output = new FreeExecutor().execute(compiled.code, ng);
  console.log(\`\n④ 실행         HTML \${output.html.length}bytes / CSS \${output.css.length}bytes / JS \${output.js.length}bytes\`);
  console.log('   HTML 미리보기:');
  output.html.split('\n').slice(0,5).forEach(l => console.log('   '+l));

  // 5. fir IR
  const ir = compiler.compileToIR(ng);
  const body = ir.ir.functions[0].body;
  console.log(\`\n⑤ fir IR       명령어 \${body.length}개\`);
  body.forEach(i => console.log(\`   \${i.op.padEnd(10)} \${(i.id||'').padEnd(4)} \${i.componentType||i.label||''}\`));

  console.log(\`\n${'═'.repeat(50)}\`);
  console.log(\` 완료: \${prompt} → HTML 생성 성공\`);
  console.log('═'.repeat(50));
}

pipeline('로그인 폼').catch(console.error);
